        const delimiter = parts[index + 1] ?? '';
        if (line.length === 0 && delimiter.length === 0) continue;
        if (run.agent !== 'codex' || !isCodexCacheError(line)) {
            this.recordOutput(run.id, 'stderr', `${line}${delimiter}`);
